/**
 * M3 mitigate station — hand-written narrowings on top of the generated site-data.ts.
 * Why a separate file: site-data.ts is regenerated by `npm run gen:types` (json2ts) and any hand edit there is
 * wiped. The schema types web_acls / errors / applied / dns of mitigate.json as bare `object`, so json2ts emits `{}`;
 * the shapes below are what radar/mitigate_station.py writes today (authoritative: that module), all fields optional
 * so an older/newer backend never crashes the page.
 */
import type { SecurityRadarSiteDataPublishedToS3ReadByTheUI, Mitigation, MitigationPlan, InspectorFinding } from './site-data';

export type { Mitigation, MitigationPlan, InspectorFinding };

/** mitigate.json root document as generated from the schema (kind = "mitigate"). */
export type MitigateDocRaw = Extract<SecurityRadarSiteDataPublishedToS3ReadByTheUI, { kind: 'mitigate' }>;
export type InspectorBaseline = MitigateDocRaw['inspector'][number];
export type InspectorBaselineState = InspectorBaseline['state'];
export type MitigationDns = NonNullable<Mitigation['dns']>;

export interface WebAclRef { target_id?: string; name?: string; id?: string }
export interface MitigateError { channel?: string; what?: string; error?: string }
export interface AppliedEntry { at?: string; web_acl?: string; rules?: string[] }
export interface MitigateDnsState {
  state?: string;
  domains?: string[];
  rules?: { name?: string; action?: string | null }[];
}

export interface MitigateDoc extends Omit<MitigateDocRaw, 'web_acls' | 'errors' | 'applied' | 'dns'> {
  web_acls: WebAclRef[];
  errors: MitigateError[];
  applied: AppliedEntry[];
  dns: MitigateDnsState | null;
}
